def subterms(x):
    out=[]
    todo=[x]
    while todo:
        y=todo.pop()
        if isinstance(y,list) and y:
            out.append(y)
            i=1
            while i<len(y):
                if isinstance(y[i],list):
                    todo.append(y[i])
                i+=1
    return out

def has_tag(x,name):
    for y in subterms(x):
        if y[0]==name:
            return True
    return False

def owner_ok(x):
    if not isinstance(x,list) or not x:
        return False
    return x[0] in ('receiving_party','party','named_recipient')

def class_tags(x,defs):
    tags=set()
    todo=[x]
    seen=set()
    while todo:
        y=todo.pop()
        if not isinstance(y,list) or not y:
            continue
        n=y[0]
        if n=='representatives_of':
            k=str(y[1]) if len(y)>1 else ''
            if k not in seen:
                seen.add(k)
                for d in defs:
                    if str(d[0])==k or (isinstance(d[0],list) and d[0] and d[0][0]=='party'):
                        todo.append(d[1])
            continue
        if n=='internal_personnel_of' and len(y)>1 and owner_ok(y[1]):
            tags.add('employees_of')
        if n in ('employees_of','directors_of','officers_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','consultants_of','agents_of','independent_contractors_of','lenders_of'):
            if len(y)>1 and owner_ok(y[1]):
                tags.add(n)
            continue
        if n=='third_parties':
            tags.add(n)
            continue
        i=1
        while i<len(y):
            if isinstance(y[i],list):
                todo.append(y[i])
            i+=1
    return tags

def unique(xs):
    out=[]
    for x in xs:
        if x not in out:
            out.append(x)
    return out

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task in ('nda-5','nda-7'):
        return apply_disclosure_update(inputs,premises)
    if task in ('nda-16','nda-20'):
        return apply_disposition_update(inputs,premises)
    return {'handled':False,'answer':None,'used_nodes':[]}

def apply_disclosure_update(inputs,premises):
    task=inputs.get('task_id')
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    byid={}
    for n in nodes:
        byid[n.get('id')]=n
    entries=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            nid=todo.pop()
            if nid in seen or nid not in byid:
                continue
            seen.add(nid)
            node=byid[nid]
            for t in subterms(node.get('term')):
                entries.append((t,root))
            for c in node.get('child_ids',[]):
                todo.append(c)
    defs=[]
    def_roots=[]
    for t,r in entries:
        if t[0]=='define_representative' and len(t)==3:
            defs.append((t[1],t[2]))
            def_roots.append(r)
    permissions=[]
    prohibitions=[]
    relevant=[]
    for t,r in entries:
        if t[0] not in ('permission','prohibition') or len(t)<3:
            continue
        action=t[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose':
            continue
        if not has_tag(action[1],'confidential_information'):
            continue
        relevant.append(r)
        tags=class_tags(action[2],defs)
        item=(r,tags,action[2])
        if t[0]=='permission':
            permissions.append(item)
        else:
            prohibitions.append(item)
    relevant=unique(relevant)
    if not relevant:
        return {'handled':False,'answer':None,'used_nodes':[]}
    wanted={'employees_of'} if task=='nda-5' else {'third_parties','consultants_of','agents_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','independent_contractors_of'}
    for r,tags,recipient in permissions:
        if tags.intersection(wanted):
            used=[r]
            if has_tag(recipient,'representatives_of'):
                used.extend(def_roots)
            return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
    for r,tags,recipient in prohibitions:
        if has_tag(recipient,'outsiders_to'):
            continue
        if tags.intersection(wanted):
            return {'handled':True,'answer':'Contradiction','used_nodes':[r]}
    return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+def_roots)}

def collect_root_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    byid={}
    for n in nodes:
        byid[n.get('id')]=n
    entries=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            nid=todo.pop()
            if nid in seen or nid not in byid:
                continue
            seen.add(nid)
            node=byid[nid]
            for t in subterms(node.get('term')):
                entries.append((t,root))
            for c in node.get('child_ids',[]):
                todo.append(c)
    return entries

def is_disposition_action(action):
    return has_tag(action,'return_to') or has_tag(action,'destroy')

def apply_disposition_update(inputs,premises):
    task=inputs.get('task_id')
    entries=collect_root_entries(premises)
    duties=[]
    retention_permissions=[]
    retention_prohibitions=[]
    for t,r in entries:
        if not isinstance(t,list) or not t:
            continue
        if t[0]=='obligation' and len(t)>=5 and is_disposition_action(t[2]) and has_tag(t[2],'confidential_information'):
            duties.append((t,r))
        if t[0]=='permission' and len(t)>=3 and has_tag(t[2],'retain') and has_tag(t[2],'confidential_information'):
            retention_permissions.append((t,r))
        if t[0]=='prohibition' and len(t)>=3 and has_tag(t[2],'retain') and has_tag(t[2],'confidential_information'):
            retention_prohibitions.append((t,r))
    if task=='nda-16':
        if not duties:
            return {'handled':False,'answer':None,'used_nodes':[]}
        relevant=[]
        for t,r in duties:
            relevant.append(r)
            trigger=t[3]
            if has_tag(trigger,'on_termination') or has_tag(trigger,'on_cessation'):
                return {'handled':True,'answer':'Entailment','used_nodes':[r]}
        request_only=False
        for t,r in duties:
            if has_tag(t[3],'on_request'):
                request_only=True
        if request_only:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if task=='nda-20':
        if retention_permissions:
            used=[]
            for t,r in retention_permissions:
                used.append(r)
            return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
        if retention_prohibitions:
            used=[]
            for t,r in retention_prohibitions:
                used.append(r)
            return {'handled':True,'answer':'Contradiction','used_nodes':unique(used)}
        exhaustive=[]
        for t,r in duties:
            if has_tag(t[2],'copies_of'):
                exhaustive.append(r)
        if exhaustive:
            return {'handled':True,'answer':'Contradiction','used_nodes':unique(exhaustive)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    return {'handled':False,'answer':None,'used_nodes':[]}

